            "protected",
            "internal",
            "open",
            "data",
            "sealed",
            "abstract",
            "final",
            "override",
            "suspend",
        ],
    );

    if let Some(after_prefix) = rest.strip_prefix("fun ") {
        return Some((
            take_identifier(after_prefix)?,
            "function".to_string(),
            visibility_from_modifiers(line.trim_start(), "public").to_string(),
        ));
    }

    for (prefix, kind) in [
        ("class ", "class"),
        ("object ", "object"),
        ("interface ", "interface"),
        ("enum class ", "enum"),
    ] {
        if let Some(after_prefix) = rest.strip_prefix(prefix) {
            return Some((
                take_identifier(after_prefix)?,
                kind.to_string(),
                visibility_from_modifiers(line.trim_start(), "public").to_string(),
            ));
        }
    }

    None
}

